python3 -I - <<'EOF'
import re,glob
fr=re.compile(r"\b(un|une|le|la|les|des|du|est|sont|ne|pas|choisit|aucune|aucun|dans|avec|cette|ses|son|sa|toutes|tout|toute|qui|que|libre|libres|exige|reste|restent|donne|mort|droit|entrée|sur|pour|par|et|ou|si|de|d|l|n|qu)\b",re.I)
en=re.compile(r"\b(the|a|an|is|of|and|to|in|on|by|with)\b",re.I)
hits={}
for f in sorted(glob.glob('formal/Ern/**/*.lean',recursive=True)):
    txt=open(f).read()
    for m in re.finditer(r'/-.*?-/',txt,re.S):
        for q in re.finditer(r'"([^"]{6,})"',m.group(0),re.S):
            s=re.sub(r'`[^`]*`','',q.group(1))
            words=re.findall(r"[A-Za-zÀ-ÿ']+",s)
            nfr=len(fr.findall(s)); nen=len(en.findall(s))
            if nfr>=2 and nfr>nen or re.search('[éèêëàâçùûîïôœ]',s):
                line=txt[:m.start()+q.start()].count('\n')+1
                hits.setdefault(f,[]).append((line,q.group(1)[:90].replace('\n',' ')))
tot=0
for f,l in hits.items():
    print(f,len(l)); tot+=len(l)
    for x in l: print('   ',x)
print('total French quotations',tot)
EOF

